WITH flattened_attrs AS (SELECT id, plan, currency, tier_limits, tier_prices, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE currency IN ('THB', 'EUR')) SELECT *, DENSE_RANK() OVER (PARTITION BY plan ORDER BY lowest_price DESC NULLS LAST) lowest_price_dense_rank, SUM(lowest_price) OVER (PARTITION BY plan, currency ORDER BY lowest_price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_lowest_price, AVG(lowest_price) OVER (PARTITION BY plan, currency ORDER BY lowest_price ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) lowest_price_avg_5, ROW_NUMBER() OVER (PARTITION BY currency ORDER BY lowest_price DESC, id ASC) event_seq, MIN(lowest_price) OVER (PARTITION BY currency, plan) currency_min_lowest_price FROM flattened_attrs;
